using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 所有对外系统（Spawner、技能效果等）应依赖 IEnemy 接口。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    // 子组件
    public EnemyHealth Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }
    public IAttackBehavior AttackBehavior { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; private set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances => SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    private void Awake()
    {
        Health = GetComponent<EnemyHealth>();
        Movement = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();
        AttackBehavior = GetComponent<IAttackBehavior>();

        if (Health == null) Health = gameObject.AddComponent<EnemyHealth>();
        if (Movement == null) Movement = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        // ═══ 单一数据源：EnemyConfig → EnemyCore → 各组件 ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth = config.maxHealth;
                Health.Initialize();
            }

            if (Movement != null)
                Movement.MoveSpeed = config.patrolSpeed;

            if (SkillManager != null)
                SkillManager.InitializeFromLibrary(config.skillLibrary);
        }
        else if (Health != null)
        {
            // 无 config 时，允许组件自身的 MaxHealth 作为默认值
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                // 切换到死亡状态
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        if (player != null) PlayerTarget = player.transform;

        // 启动默认状态（若存在巡逻点则 Patrol，否则 Idle）
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        // 优先从 MeleeAttack 组件读取伤害值
        if (AttackBehavior is MeleeAttack melee)
            return melee.damage;
        if (AttackBehavior is RangedAttack ranged)
            return ranged.damage;
        return 10f;
    }

    /// <summary>
    /// 施法者阵营：被同化后为 Player（技能命中 Enemy），否则为 Enemy（技能命中 Player）。
    /// </summary>
    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    // ---------- 同化 ----------
    /// <summary>
    /// 将被侵蚀的敌人转化为玩家的随从。
    /// - 改 tag 为 Player（让其他敌人的攻击能命中此随从）
    /// - 禁用原状态机，由 EnemyFollower 接管 AI
    /// - 清除旧的死亡事件，由 EnemyFollower 处理死亡
    /// </summary>
    public void Assimilate(Transform playerTarget)
    {
        // 1. 标记已同化（房间/生成器通过 OnAssimilated 事件从存活列表移除）
        IsAssimilated = true;

        // 2. 清除旧的死亡订阅（由 EnemyFollower 接管死亡处理）
        if (Health != null)
            Health.ClearOnDied();

        // 3. 通知外部系统：此敌人不再是敌人
        OnAssimilated?.Invoke(this);

        // 4. 改 tag，使敌人攻击能命中此随从
        gameObject.tag = "Player";

        // 5. 禁用原有状态机
        if (StateMachine != null)
            StateMachine.enabled = false;

        // 6. 停止当前移动
        Movement?.Stop();

        // 7. 添加并激活随从组件
        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        // 8. 更新玩家引用（供技能方向等使用）
        PlayerTarget = playerTarget;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 统一敌人对外接口，供生成器、技能及其它系统使用。
/// 重构目标是让外部通过接口而非具体 BaseEnemy 类型交互。
/// </summary>
public interface IEnemy : IDamageable, ISkillCaster
{
    /// <summary>用于外部查询或定位的 Transform 引用</summary>
    Transform EnemyTransform { get; }

    /// <summary>敌人是否已死亡</summary>
    bool IsDead { get; }

    /// <summary>是否已被同化为随从（房间/生成器应排除）</summary>
    bool IsAssimilated { get; }

    /// <summary>敌人当前持有的技能实例（只读）</summary>
    IReadOnlyList<SkillInstance> SkillInstances { get; }

    /// <summary>敌人死亡事件（触发时表示该敌人已死亡/即将销毁）</summary>
    event Action OnDied;

    /// <summary>敌人被同化为随从事件（触发时房间/生成器应从存活列表移除）</summary>
    event Action<IEnemy> OnAssimilated;
}

using System;
using UnityEngine;

/// <summary>
/// 敌人生存组件，负责血量管理并通过委托广播变化。
/// 实现 IDamageable 以便外部统一调用。
///
/// 数据源：MaxHealth 由 EnemyCore（或外部）在 Awake 后显式赋值，
///         然后调用 Initialize() 完成初始化。不在 Awake 中自动初始化。
/// </summary>
public class EnemyHealth : MonoBehaviour, IDamageable
{
    [Header("生命")]
    [Tooltip("由 EnemyCore 根据 EnemyConfig 赋值，也可独立设置")]
    public float MaxHealth = 30f;

    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;

    /// <summary>
    /// 由 EnemyCore 在设置 MaxHealth 后调用。
    /// 确保 _health 从最终 MaxHealth 初始化，避免数据源不一致。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;

        _health = MaxHealth;
        _initialized = true;
    }

    private void Awake()
    {
        // 不再自动初始化，由调用方（EnemyCore）控制初始化时机
    }

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        // 弹出伤害数字
        DamagePopup.Spawn(transform.position, damage);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
        {
            Die();
        }
    }

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>
    /// 清除 OnDied 事件的所有订阅者（用于同化时切换死亡处理逻辑）。
    /// </summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }
}

using UnityEngine;

/// <summary>
/// 移动组件：封装 Rigidbody2D 操作与视线检测缓存。
///
/// 速度数据源： EnemyConfig.patrolSpeed / EnemyConfig.chaseSpeed
///             由状态机在 Enter 时写入 MoveSpeed，组件本身不做初始化。
/// </summary>
[RequireComponent(typeof(Rigidbody2D))]
public class EnemyMovement : MonoBehaviour
{
    /// <summary>运行时当前速度（由状态机从 EnemyConfig 赋值，不在 Inspector 设置）</summary>
    [HideInInspector]
    public float MoveSpeed = 2f;

    private Rigidbody2D _rb;
    private float _nextSightCheckTime;
    private bool _cachedHasLineOfSight;
    private bool _wasInDetectionRange = false;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (_rb != null) _rb.freezeRotation = true;
    }

    public void Stop()
    {
        if (_rb != null) _rb.velocity = Vector2.zero;
    }

    public void MoveTowardsPosition(Vector2 target, float speedMultiplier = 1f)
    {
        if (_rb == null) return;
        Vector2 dir = (target - (Vector2)transform.position).normalized;
        _rb.velocity = dir * MoveSpeed * speedMultiplier;
    }

    public void SetVelocity(Vector2 vel)
    {
        if (_rb == null) return;
        _rb.velocity = vel;
    }

    /// <summary>直接传送到目标位置（通过 Rigidbody2D.position）</summary>
    public void Teleport(Vector2 targetPos)
    {
        if (_rb != null)
        {
            _rb.velocity = Vector2.zero;
            _rb.position = targetPos;
        }
        else
        {
            transform.position = targetPos;
        }
    }

    /// <summary>
    /// 带缓存的视线检测。调用时会基于 interval 减少 Linecast 次数。
    /// </summary>
    public bool HasLineOfSight(Vector2 targetPosition, float detectionRange, float sightCheckInterval = 0.2f)
    {
        float sqrDistance = ((Vector2)transform.position - targetPosition).sqrMagnitude;
        bool inRange = sqrDistance <= detectionRange * detectionRange;

        if (!inRange)
        {
            _wasInDetectionRange = false;
            _cachedHasLineOfSight = false;
            return false;
        }

        if (!_wasInDetectionRange)
        {
            _nextSightCheckTime = 0f; // force immediate check
            _wasInDetectionRange = true;
        }

        if (Time.time >= _nextSightCheckTime)
        {
            _nextSightCheckTime = Time.time + sightCheckInterval;
            RaycastHit2D hit = Physics2D.Linecast(transform.position, targetPosition);
            _cachedHasLineOfSight = hit.collider == null || !hit.collider.CompareTag("Wall");
        }

        return _cachedHasLineOfSight;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人的技能管理组件：负责装配技能、驱动冷却并提供 TryCast 接口。
/// </summary>
public class EnemySkillManager : MonoBehaviour
{
    private List<SkillInstance> _skillInstances = new List<SkillInstance>();

    public IReadOnlyList<SkillInstance> SkillInstances => _skillInstances;

    public void InitializeFromLibrary(SkillLibrary library, int randomMin = 1, int randomMax = 2)
    {
        _skillInstances.Clear();
        if (library == null) return;

        var datas = library.GetRandomDistinct(Random.Range(randomMin, randomMax + 1));
        foreach (var d in datas)
        {
            if (d == null) continue;
            var inst = library.CreateSkillInstance(d.skillId);
            if (inst != null) _skillInstances.Add(inst);
        }
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        foreach (var s in _skillInstances)
            s.TickCooldown(dt);
    }

    public bool TryCastSkill(int index, ISkillCaster caster, Vector2 dir)
    {
        if (index < 0 || index >= _skillInstances.Count) return false;
        return _skillInstances[index].TryCast(caster, dir);
    }
}

using UnityEngine;

/// <summary>
/// 攻击状态：停止移动，尝试用 IAttackBehavior 和技能攻击玩家。
/// 玩家离开攻击范围 → Chase。
/// </summary>
public class AttackState : EnemyStateBase
{
    public AttackState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.config == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float attackSqr = Core.config.attackRange * Core.config.attackRange;

        // 玩家离开攻击范围 → 继续追击
        if (sqrDist > attackSqr * 1.2f)
        {
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // 尝试使用攻击行为
        Core.AttackBehavior?.TryAttack(Core.PlayerTarget);

        // 尝试释放技能
        if (Core.SkillManager != null && Core.SkillManager.SkillInstances.Count > 0)
        {
            Core.SkillManager.TryCastSkill(0, Core, Core.GetTargetDirection());
        }
    }
}

using UnityEngine;

/// <summary>
/// 追击状态：加速追向玩家。进入攻击范围 → Attack；丢失视线 → Search；脱离探测范围 → Patrol/Idle。
/// </summary>
public class ChaseState : EnemyStateBase
{
    public ChaseState(EnemyCore core) : base(core) { }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.config == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float detectionSqr = Core.config.detectionRange * Core.config.detectionRange;
        float attackSqr = Core.config.attackRange * Core.config.attackRange;

        // 超出探测范围 → 返回巡逻/空闲
        if (sqrDist > detectionSqr)
        {
            Core.Movement?.Stop();
            if (Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
                Core.StateMachine.ChangeState(new PatrolState(Core));
            else
                Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // 视线检测
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange);

        if (!canSee)
        {
            // 丢失视线 → 搜索
            Core.StateMachine.ChangeState(new SearchState(Core));
            return;
        }

        Core.LastKnownPlayerPosition = playerPos;

        // 进入攻击范围
        if (sqrDist <= attackSqr)
        {
            Core.StateMachine.ChangeState(new AttackState(Core));
            return;
        }

        // 追击移动（加速）
        if (Core.Movement != null)
        {
            Core.Movement.MoveSpeed = Core.config.chaseSpeed;
            Core.Movement.MoveTowardsPosition(playerPos);
        }
    }
}

using UnityEngine;

/// <summary>
/// 空闲状态：原地待命，定期检测玩家。发现玩家 → Chase；有巡逻点 → Patrol。
/// </summary>
public class IdleState : EnemyStateBase
{
    public IdleState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null) return;
        if (Core.config == null) return;

        // 检测玩家
        Vector2 playerPos = Core.PlayerTarget.position;
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange);

        if (canSee)
        {
            Core.LastKnownPlayerPosition = playerPos;
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // 有巡逻点则转入巡逻
        if (Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
        {
            Core.StateMachine.ChangeState(new PatrolState(Core));
            return;
        }
    }
}

using UnityEngine;

/// <summary>
/// 死亡状态：停止移动、禁用碰撞，延迟销毁 GameObject。
/// </summary>
public class DeadState : EnemyStateBase
{
    private float _destroyDelay = 0.5f;
    private float _deadTime;

    public DeadState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _deadTime = Time.time;

        Core.Movement?.Stop();

        // 禁用所有 Collider2D 防止死亡后继续触发碰撞
        foreach (var col in Core.GetComponentsInChildren<Collider2D>())
        {
            col.enabled = false;
        }
    }

    public override void Tick()
    {
        if (Time.time - _deadTime >= _destroyDelay)
        {
            Object.Destroy(Core.gameObject);
        }
    }
}

using UnityEngine;

/// <summary>
/// 巡逻状态：沿配置的 patrolPoints 逐个移动，到达后在每个点短暂停留。
/// 发现玩家 → Chase。
/// </summary>
public class PatrolState : EnemyStateBase
{
    private int _currentIndex;
    private float _waitTimer;
    private static readonly float WaitPerPoint = 0.8f;
    private static readonly float ArriveThreshold = 0.3f;

    public PatrolState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _currentIndex = 0;
        _waitTimer = 0f;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget != null && Core.config != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        if (Core.config == null || Core.config.patrolPoints == null || Core.config.patrolPoints.Count == 0)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 target = Core.config.patrolPoints[_currentIndex];
        float sqrDist = ((Vector2)Core.transform.position - target).sqrMagnitude;

        if (sqrDist < ArriveThreshold * ArriveThreshold)
        {
            // 到达，等待
            Core.Movement?.Stop();
            _waitTimer += Time.deltaTime;
            if (_waitTimer >= WaitPerPoint)
            {
                _waitTimer = 0f;
                _currentIndex = (_currentIndex + 1) % Core.config.patrolPoints.Count;
            }
        }
        else
        {
            _waitTimer = 0f;
            Core.Movement?.MoveTowardsPosition(target);
            // 巡逻用 patrolSpeed
            if (Core.Movement != null)
                Core.Movement.MoveSpeed = Core.config.patrolSpeed;
        }
    }
}

using UnityEngine;

/// <summary>
/// 搜索状态：移动到玩家最后已知位置，到达后等待 searchDuration 秒。
/// 重新发现玩家 → Chase；超时 → Patrol/Idle。
/// </summary>
public class SearchState : EnemyStateBase
{
    private float _enterTime;
    private float _searchDuration = 2.5f;
    private bool _arrived;
    private static readonly float ArriveThreshold = 0.4f;

    public SearchState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _enterTime = Time.time;
        _arrived = false;
    }

    public override void Tick()
    {
        // 期间重新发现玩家 → 立即追击
        if (Core.PlayerTarget != null && Core.config != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        Vector2 lastPos = Core.LastKnownPlayerPosition;
        float sqrDist = ((Vector2)Core.transform.position - lastPos).sqrMagnitude;

        if (!_arrived)
        {
            if (sqrDist < ArriveThreshold * ArriveThreshold)
            {
                _arrived = true;
                _enterTime = Time.time; // 重置计时，开始等待
                Core.Movement?.Stop();
            }
            else
            {
                Core.Movement?.MoveTowardsPosition(lastPos, 0.8f);
            }
        }
        else
        {
            Core.Movement?.Stop();
            if (Time.time - _enterTime > _searchDuration)
            {
                // 超时，返回巡逻或空闲
                if (Core.config != null && Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
                    Core.StateMachine.ChangeState(new PatrolState(Core));
                else
                    Core.StateMachine.ChangeState(new IdleState(Core));
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 攻击行为策略接口，允许不同攻击方式作为组件插入到敌人 Prefab。
/// </summary>
public interface IAttackBehavior
{
    /// <summary>尝试执行一次攻击，返回是否成功触发（用于AI调度）</summary>
    bool TryAttack(Transform target);
}

using UnityEngine;

[RequireComponent(typeof(Collider2D))]
public class MeleeAttack : MonoBehaviour, IAttackBehavior
{
    [Header("近战攻击")]
    public float damage = 10f;
    public float attackCooldown = 1.0f;

    /// <summary>
    /// 攻击阵营：Enemy=命中Player / Player=命中Enemy。
    /// 随从同化后 EnemyFollower 会将其设为 Player，避免误伤玩家和友军。
    /// </summary>
    [Tooltip("攻击阵营：Enemy=命中Player / Player=命中Enemy")]
    public Projectile.OwnerType ownerType = Projectile.OwnerType.Enemy;

    private float _lastAttackTime = -10f;

    public bool TryAttack(Transform target)
    {
        if (Time.time < _lastAttackTime + attackCooldown) return false;
        if (target == null) return false;

        var dmg = target.GetComponent<IDamageable>();
        if (dmg != null)
        {
            dmg.TakeDamage(damage);
            _lastAttackTime = Time.time;
            return true;
        }

        return false;
    }

    private void OnTriggerStay2D(Collider2D other)
    {
        // 根据阵营确定命中 Tag
        string targetTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        if (Time.time < _lastAttackTime + attackCooldown) return;

        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            _lastAttackTime = Time.time;
        }
    }
}

using UnityEngine;

/// <summary>
/// 远程攻击行为：定时朝玩家发射投射物。
/// 投射物预制体需挂有 Projectile 组件，RangedAttack 通过 Initialize() 配置其飞行参数。
/// </summary>
public class RangedAttack : MonoBehaviour, IAttackBehavior
{
    [Header("远程攻击")]
    public float damage = 8f;
    [Tooltip("两次攻击间隔（秒）")]
    public float attackCooldown = 1.5f;
    [Tooltip("投射物预制体（需挂有 Projectile 组件）")]
    public GameObject projectilePrefab;
    public float projectileSpeed = 6f;
    [Tooltip("投射物生成偏移（相对敌人位置）")]
    public Vector2 spawnOffset = Vector2.up * 0.5f;
    public float projectileLifetime = 3f;
    [Tooltip("投射物阵营：Enemy=命中Player / Player=命中Enemy（随从同化后应为Player）")]
    public Projectile.OwnerType projectileOwnerType = Projectile.OwnerType.Enemy;

    private float _lastAttackTime = -10f;

    public bool TryAttack(Transform target)
    {
        if (Time.time < _lastAttackTime + attackCooldown) return false;
        if (target == null) return false;
        if (projectilePrefab == null) return false;

        Vector2 dir = (target.position - transform.position).normalized;
        Vector2 spawnPos = (Vector2)transform.position + spawnOffset;

        GameObject obj = Instantiate(projectilePrefab, spawnPos, Quaternion.identity);
        Projectile proj = obj.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(dir, projectileSpeed, damage, projectileOwnerType, gameObject);
        }
        else
        {
            // 回退：无 Projectile 组件则手动销毁
            Destroy(obj, projectileLifetime);
        }

        _lastAttackTime = Time.time;
        return true;
    }
}

using System;
